floor_fn:
"""
    Returns number of seconds from track data based on frequency
    :param track: wav audio data
    :param freq: frequency of audio data
    :return: number of seconds
    """
def seconds(data: Any, freq: Any) -> object {
    return (len(data) / freq);
}

test_blocks:
test "t0" {
    assert (seconds(b'', 8000) == 0);;
}

test "t1" {
    assert (seconds(b'', 44100) == 0);;
}

test "t2" {
    assert (seconds((b'\x00' * 44100 * 10), 44100) == 10) , "10 seconds at 44100 Hz";;
}

test "t3" {
    assert (seconds((b'\x00' * 44100 * 1000), 22050) == 2000) , "1000 seconds at 22050 Hz";;
}

test "t4" {
    assert (seconds(b'asdf', 1) == 4);;
}

test "t5" {
    assert (seconds((b'\x00' * 48000), 48000) == 1);;
}

test "t6" {
    assert (seconds(b'', 48000) == 0);;
}

test "t7" {
    assert (seconds((b'\x00' * 44100 * 2), 44100) == 2);;
}

test "t8" {
    assert (seconds((b'\x00' * 44100), 22050) == 2);;
}

test "t9" {
    assert (seconds(bytearray(b''), 44100) == 0);;
}

test "t10" {
    assert (seconds((b'\x00' * 44100), 44100) == 1);;
}

test "t11" {
    assert (seconds(bytearray([0, 1, 2, 3, 4, 5]), 1) == 6);;
}

test "t12" {
    assert (seconds(b'asdf', 4) == 1);;
}

test "t13" {
    assert (seconds(b'asdf', 2) == 2);;
}

test "t14" {
    assert (seconds((b'\x00' * 44100 * 1000), 44100) == 1000) , "1000 seconds at 44100 Hz";;
}

test "t15" {
    assert (seconds(bytearray([0, 1, 2, 3, 4, 5]), 2) == 3);;
}

test "t16" {
    assert (seconds(b'111', 1) == 3);;
}
